def creer_donnees_demo(n=300):
    rng = np.random.default_rng(42)
    age = rng.integers(18, 90, n)
    imc = np.clip(rng.normal(27, 5.5, n), 15, 48).round(1)
    fumeur = rng.choice(["Oui", "Non"], n, p=[0.32, 0.68])
    hospitalisations = np.clip(rng.poisson(1.2, n), 0, 10)
    sexe = rng.choice(["Femme", "Homme"], n)
    region = rng.choice(["Thiès", "Dakar", "Diourbel", "Louga", "Saint-Louis"], n)
    return pd.DataFrame({
        "Patient_ID": [f"P-{i:05d}" for i in range(1, n + 1)],
        "Age": age, "Sexe": sexe, "IMC": imc, "Fumeur": fumeur,
        "Hospitalisations": hospitalisations, "Region": region,
    })


def lire_fichier_csv(fichier):
    """Lit tout le contenu CSV sans limite de lignes, avec encodages et séparateurs courants."""
    # Streamlit peut relancer l'application après l'importation : getvalue() relit
    # tous les octets à chaque rerun, contrairement à read() qui vide le curseur.
    if hasattr(fichier, "getvalue"):
        contenu = fichier.getvalue()
    elif hasattr(fichier, "read_bytes"):
        contenu = fichier.read_bytes()
    elif hasattr(fichier, "read"):
        contenu = fichier.read()
    else:
        contenu = Path(fichier).read_bytes()

    if not contenu:
        raise ValueError("Le fichier CSV est vide ou son contenu n'a pas pu être lu.")

    from io import BytesIO
    derniere_erreur = None
    for encodage in ("utf-8-sig", "utf-8", "cp1252", "latin1"):
        for separateur in (None, ";", ",", "\t", "|"):
            try:
                options = {"encoding": encodage, "low_memory": False}
                if separateur is None:
                    df = pd.read_csv(BytesIO(contenu), sep=None, engine="python", **options)
                else:
                    df = pd.read_csv(BytesIO(contenu), sep=separateur, **options)
                df.columns = [str(c).strip().replace("\ufeff", "") for c in df.columns]
                # Écarter un séparateur qui aurait placé tout le fichier dans une seule colonne.
                if len(df.columns) == 1 and any(sep in contenu[:4096].decode(encodage, errors="ignore") for sep in (";", ",", "\t", "|")):
                    derniere_erreur = ValueError("Le séparateur du CSV n'a pas été détecté correctement.")
                    continue
                if len(df) == 0:
                    raise ValueError("Le CSV ne contient aucune ligne de données.")
                return df
            except Exception as exc:
                derniere_erreur = exc
    raise ValueError(
        "Impossible de lire le fichier CSV. Vérifiez son séparateur et son contenu. "
        f"Détail : {derniere_erreur}"
    )


def charger_donnees():
    # Le fichier local automatique est également limité au format CSV.
    chemin = Path("patients.csv")
    if chemin.exists() and chemin.suffix.lower() == ".csv":
        try:
            return lire_fichier_csv(chemin), "Fichier patients.csv"
        except Exception as exc:
            st.warning(f"Lecture de patients.csv impossible : {exc}. Utilisation des données de démonstration.")
    return creer_donnees_demo(), "Données fictives de démonstration (importez un CSV pour vos données)"


def preparer_donnees(df):
    df = df.copy()
    colonnes = ["Patient_ID", "Age", "Sexe", "IMC", "Fumeur", "Hospitalisations", "Region"]
    valeurs_defaut = {"Age": 40, "Sexe": "Inconnu", "IMC": 25, "Fumeur": "Non", "Hospitalisations": 0, "Region": "Non renseignée"}
    for col in colonnes:
        if col not in df.columns:
            if col == "Patient_ID":
                df[col] = [f"P-{i:05d}" for i in range(1, len(df) + 1)]
            else:
                df[col] = valeurs_defaut[col]
    for col in ["Age", "IMC", "Hospitalisations"]:
        df[col] = pd.to_numeric(df[col], errors="coerce")
        mediane = df[col].median()
        df[col] = df[col].fillna(mediane if pd.notna(mediane) else valeurs_defaut[col])
    for col in ["Sexe", "Fumeur", "Region", "Patient_ID"]:
        df[col] = df[col].fillna("Inconnu").astype(str).str.strip()
    df["Age"] = df["Age"].clip(0, 120)
    df["IMC"] = df["IMC"].clip(0, 100)
    df["Hospitalisations"] = df["Hospitalisations"].clip(lower=0).round().astype(int)
    df["Fumeur_binaire"] = df["Fumeur"].str.lower().map({
        "oui": 1, "yes": 1, "1": 1, "true": 1,
        "non": 0, "no": 0, "0": 0, "false": 0,
    }).fillna(0).astype(int)
    df["Fumeur"] = np.where(df["Fumeur_binaire"] == 1, "Oui", "Non")
    return df

# =========================================================
# 4. SEGMENTATION CAH
# =========================================================
FEATURES = ["Age", "IMC", "Fumeur_binaire", "Hospitalisations"]


def calculer_segmentation(df):
    df = df.copy()
    if len(df) == 0:
        return df, None, None
    X = df[FEATURES].astype(float)
    scaler = StandardScaler()
    X_scaled = scaler.fit_transform(X)
    if len(df) < 3:
        df["Cluster"] = 0
        df["Profil"] = PROFILS[0]
        return df, scaler, X_scaled
    model = AgglomerativeClustering(n_clusters=3, linkage="ward")
    df["Cluster"] = model.fit_predict(X_scaled)
    stats = df.groupby("Cluster").agg(
        age_moyen=("Age", "mean"), imc_moyen=("IMC", "mean"),
        taux_fumeurs=("Fumeur_binaire", "mean"),
        hospitalisations_moyennes=("Hospitalisations", "mean"),
    )
    score_senior = stats["age_moyen"].rank(pct=True) + stats["hospitalisations_moyennes"].rank(pct=True)
    cluster_senior = int(score_senior.idxmax())
    autres = [c for c in stats.index if c != cluster_senior]
    if len(autres) >= 2:
        score_fumeur = stats.loc[autres, "imc_moyen"].rank(pct=True) + stats.loc[autres, "taux_fumeurs"].rank(pct=True)
        cluster_fumeur = int(score_fumeur.idxmax())
        cluster_routine = next(c for c in autres if c != cluster_fumeur)
    else:
        cluster_fumeur = autres[0] if autres else cluster_senior
        cluster_routine = cluster_fumeur
    mapping = {cluster_routine: PROFILS[0], cluster_senior: PROFILS[1], cluster_fumeur: PROFILS[2]}
    df["Profil"] = df["Cluster"].map(mapping).fillna(PROFILS[0])
    return df, scaler, X_scaled

