# 5. ALERTES ET RECOMMANDATIONS INDICATIVES
# =========================================================
def generer_alertes(df):
    df = df.copy()
    if df.empty:
        df["Nombre_facteurs_alerte"] = []
        df["Niveau_alerte"] = []
        df["Recommandation"] = []
        return df
    conditions = [df["Age"] >= 65, df["IMC"] >= 30, df["Hospitalisations"] >= 3, df["Fumeur_binaire"] == 1]
    df["Nombre_facteurs_alerte"] = sum(condition.astype(int) for condition in conditions)
    def niveau(nombre):
        if nombre >= 3: return "Rouge"
        if nombre == 2: return "Orange"
        if nombre == 1: return "Jaune"
        return "Vert"
    df["Niveau_alerte"] = df["Nombre_facteurs_alerte"].apply(niveau)
    def recommandation(row):
        pistes = []
        if row["Age"] >= 65: pistes.append("Examiner les besoins de suivi liés à l'âge")
        if row["IMC"] >= 30: pistes.append("Évaluer les facteurs associés à l'IMC")
        if row["Hospitalisations"] >= 3: pistes.append("Revoir l'historique des hospitalisations")
        if row["Fumeur_binaire"] == 1: pistes.append("Évaluer les besoins d'accompagnement au sevrage")
        return " ; ".join(pistes) + "." if pistes else "Poursuivre le suivi selon le dossier clinique."
    df["Recommandation"] = df.apply(recommandation, axis=1)
    return df

