# Préparation KNN à partir des caractéristiques du CSV (hors identifiants et colonnes calculées).
COLONNES_TECHNIQUES = {
    "Fumeur_binaire", "Cluster", "Profil", "Nombre_facteurs_alerte",
    "Niveau_alerte", "Recommandation"
}
def est_identifiant(nom):
    normalise = "".join(ch.lower() for ch in str(nom) if ch.isalnum())
    termes_identifiant = ("patientid", "idpatient", "identifiant", "numero dossier", "numerodossier", "telephone", "email", "adresse", "nompatient", "prenompatient")
    return normalise in {"id", "idpatient", "patientid", "uuid", "email", "telephone", "phone"} or any(t.replace(" ", "") in normalise for t in termes_identifiant)

colonnes_knn = []
for col in df_base.columns:
    if col in COLONNES_TECHNIQUES or est_identifiant(col):
        continue
    if df_base[col].notna().sum() == 0 or df_base[col].nunique(dropna=True) <= 1:
        continue
    colonnes_knn.append(col)

knn = None
label_encoder = None
scaler_knn = None
colonnes_encodees = []
X_knn = None
if len(df_segmente) >= 3 and df_segmente["Profil"].nunique() >= 1 and colonnes_knn:
    donnees_knn = df_base[colonnes_knn].copy()
    for col in colonnes_knn:
        if pd.api.types.is_numeric_dtype(donnees_knn[col]):
            donnees_knn[col] = pd.to_numeric(donnees_knn[col], errors="coerce")
            med = donnees_knn[col].median()
            donnees_knn[col] = donnees_knn[col].fillna(0 if pd.isna(med) else med)
        else:
            donnees_knn[col] = donnees_knn[col].fillna("Non renseigné").astype(str).str.strip()
    X_knn = pd.get_dummies(donnees_knn, dummy_na=False, dtype=float)
    # Écarter les colonnes constantes après encodage.
    X_knn = X_knn.loc[:, X_knn.nunique(dropna=False) > 1]
    colonnes_encodees = list(X_knn.columns)
    if X_knn.shape[1] > 0:
        scaler_knn = StandardScaler()
        X_knn_scaled = scaler_knn.fit_transform(X_knn.astype(float))
        label_encoder = LabelEncoder()
        y = label_encoder.fit_transform(df_segmente["Profil"].astype(str))
        knn = KNeighborsClassifier(n_neighbors=min(5, len(df_segmente)))
        knn.fit(X_knn_scaled, y)

